import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
import { edit_project } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
import CountryList from "@/JsonFiles/CountryList.json";
import { list_all_user_projects } from "@/graphql/queries.js";
export default {
  props: {
    addProjectMemberDialogue: Boolean,
    projData: Object
  },
  mixins: [get_all_org_users],
  data() {
    return {
      teamMembers: "",
      searchF: "",
      userArray: [],
      userRole: "",
      loading: false,
      memberType: "",
      countryitems: [],
      projectMembers: [],
      roleItems: ["Member", "Observer"],
      contactNumber: "",
      countrycode: "+91",
      externalEmail: "",
      externalUserName: ""
    };
  },
  watch: {
    addProjectMemberDialogue: {
      async handler() {
        if (this.addProjectMemberDialogue == true) {
          this.$store.commit("Setnamesearch", "");
          this.memberType = "";
          await this.get_all_org_users();
          this.fetch_project_list();
          this.fetch_details();
        }
      },
      immediate: true
    }
  },
  methods: {
    async fetch_project_list() {
      try {
        let result = await API.graphql(graphqlOperation(list_all_user_projects, {
          input: {
            project_progress: "ALL"
          }
        }));
        var response = JSON.parse(result.data.list_all_user_projects);
        if (response.Status == "SUCCESS") {
          this.projectMembers = [];
          response.data.forEach(element => {
            if (element.project_id == this.projData.project_id) {
              this.projectMembers = element.project_visible_members;
            }
          });
        } else {
          this.projectMembers = [];
        }
      } catch (error) {
        console.log(error);
      }
    },
    close_dialog() {
      this.$emit("clicked", 0);
    },
    cleardata() {
      this.teamMembers = "";
      this.userRole = "";
      this.externalUserName = "";
      this.externalEmail = "";
      this.contactNumber = "";
    },
    is_number(evt) {
      evt = evt ? evt : window.event;
      var charCode = evt.which ? evt.which : evt.keyCode;
      if (charCode > 31 && (charCode < 48 || charCode > 57) && charCode !== 46) {
        evt.preventDefault();
      } else {
        return true;
      }
    },
    process(event) {
      if (event.type == "paste") {
        var clipboardData = event.clipboardData || window.clipboardData;
        var pastedData = clipboardData.getData("Text");
        if (isNaN(pastedData)) {
          event.preventDefault();
        } else {
          return;
        }
      }
      var keyCode = event.keyCode || event.which;
      if (keyCode >= 96 && keyCode <= 105) {
        keyCode -= 48;
      }
      var charValue = String.fromCharCode(keyCode);
      if (isNaN(parseInt(charValue)) && event.keyCode != 8) {
        event.preventDefault();
      }
    },
    fetch_details() {
      this.orgUsers.forEach(element => {
        if (element.user_status == "ACTIVE") {
          this.userArray.push({
            full_user_name: element.full_user_name,
            user_email_id: element.user_email_id,
            user_country_code: element.user_country_code,
            user_contact_number: element.user_contact_number
          });
        }
      });
      CountryList.forEach(element => {
        this.countryitems.push({
          name: element.name + "(" + element.dial_code + ")",
          code: element.dial_code
        });
      });
    },
    async validate_data() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid && this.memberType != "") {
        let existing = this.projectMembers;
        let data = {
          name: this.memberType == "INTERNAL" ? this.teamMembers.full_user_name : this.externalUserName,
          email: this.memberType == "INTERNAL" ? this.teamMembers.user_email_id : this.externalEmail,
          role: this.memberType == "INTERNAL" ? this.userRole : "",
          member_type: this.memberType,
          countryCode: this.memberType == "EXTERNAL" ? this.countrycode : this.teamMembers.user_country_code == "N/A" ? "" : this.teamMembers.user_country_code,
          contactNumber: this.memberType == "EXTERNAL" ? this.contactNumber : this.teamMembers.user_contact_number == "N/A" ? "" : this.teamMembers.user_contact_number
        };
        const dataExisits = existing.some(currentdata => currentdata.email === data.email);
        if (dataExisits) {
          this.$emit("errorMsg", "User already Exist");
        } else {
          this.add_users_team();
        }
      }
    },
    async add_users_team() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(edit_project, {
          input: {
            project_id: this.projData.project_id,
            project_visible_members: this.fetch_users()
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.edit_project);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.teamMembers = [];
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    },
    fetch_users() {
      let allMembers = [];
      let data = {
        name: this.memberType == "INTERNAL" ? this.teamMembers.full_user_name : this.externalUserName,
        email: this.memberType == "INTERNAL" ? this.teamMembers.user_email_id : this.externalEmail,
        role: this.memberType == "INTERNAL" ? this.userRole : "",
        member_type: this.memberType,
        countryCode: this.memberType == "EXTERNAL" ? this.countrycode : this.teamMembers.user_country_code == "N/A" ? "" : this.teamMembers.user_country_code,
        contactNumber: this.memberType == "EXTERNAL" ? this.contactNumber : this.teamMembers.user_contact_number == "N/A" ? "" : this.teamMembers.user_contact_number
      };
      allMembers.push(data);
      var existing = this.projectMembers;
      var newData = allMembers;
      var final = existing.concat(newData);
      return JSON.stringify(final);
    }
  }
};
